mapper.select:
SELECT r.goods as goodsId, r.attr as attrName, SUM(r.nums) as attrStock FROM is_room r WHERE r.goods IN
#{goodsId}
AND r.attr IS NOT NULL AND r.attr != ''
AND r.warehouse IN
#{warehouseId}
GROUP BY r.goods, r.attr

SELECT b.id as batchId, b.goods as goodsId, r.attr as attrName, b.number as batchNumber, DATE(FROM_UNIXTIME(b.time)) as productDate, w.name as warehouseName, b.nums FROM is_batch b LEFT JOIN is_warehouse w ON b.warehouse = w.id LEFT JOIN is_room r ON b.room = r.id WHERE b.goods IN
#{goodsId}
AND b.number LIKE CONCAT('%', #{query.batchNumber}, '%')
AND DATE(FROM_UNIXTIME(b.time)) = #{query.productDate}
AND b.nums <= ( SELECT g.stock FROM is_goods g WHERE g.id = b.goods )
AND b.warehouse IN
#{warehouseId}
ORDER BY b.goods, r.attr, b.number, b.warehouse
